-- Additive reporting ledger; original financial facts and legacy progress remain unchanged.
CREATE TABLE management_values (
 organization_id TEXT NOT NULL REFERENCES organizations(id),
 entity_type TEXT NOT NULL CHECK(entity_type IN ('finance_period','finance_month','kpi')),
 entity_id TEXT NOT NULL, metric TEXT NOT NULL,
 scenario TEXT NOT NULL CHECK(scenario IN ('actual','budget','forecast','prior_year')),
 period TEXT NOT NULL, value REAL, is_closed INTEGER NOT NULL DEFAULT 0 CHECK(is_closed IN (0,1)),
 source TEXT NOT NULL DEFAULT '架空/未締め', updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
 version INTEGER NOT NULL DEFAULT 1,
 PRIMARY KEY(entity_type,entity_id,metric,scenario,period)
);
CREATE INDEX management_values_org ON management_values(organization_id);
CREATE TABLE management_milestones (
 id TEXT PRIMARY KEY, initiative_id TEXT NOT NULL REFERENCES initiatives(id),
 title TEXT NOT NULL, planned_on TEXT NOT NULL, completed_on TEXT,
 version INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
INSERT INTO management_values(organization_id,entity_type,entity_id,metric,scenario,period,value,updated_at) SELECT b.organization_id,'finance_period',t.id,'revenue','actual',CAST(t.fiscal_year AS TEXT),t.revenue,t.updated_at FROM finance_periods t JOIN finance_business_units b ON b.id=t.business_unit_id;
