CREATE TRIGGER management_sync_finance_periods AFTER UPDATE OF revenue,cost_of_sales,sga,tax_rate,opening_invested_capital,opening_assets,opening_cash,receivables,inventory,payables,fixed_assets,short_term_debt,long_term_debt,operating_cf,investing_cf,financing_cf ON finance_periods BEGIN
UPDATE management_values SET is_closed=CASE WHEN value IS NOT NEW.revenue THEN 0 ELSE is_closed END,value=NEW.revenue,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE entity_type='finance_period' AND entity_id=NEW.id AND metric='revenue' AND scenario='actual';
UPDATE management_values SET is_closed=CASE WHEN value IS NOT NEW.cost_of_sales THEN 0 ELSE is_closed END,value=NEW.cost_of_sales,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE entity_type='finance_period' AND entity_id=NEW.id AND metric='cost_of_sales' AND scenario='actual';
