INSERT INTO management_values(organization_id,entity_type,entity_id,metric,scenario,period,value) SELECT b.organization_id,'finance_month',t.id,'revenue','actual',printf('%04d-%02d',p.fiscal_year + (t.month_index+3)/12,(t.month_index+3)%12+1),t.revenue FROM finance_months t JOIN finance_periods p ON p.id=t.finance_period_id JOIN finance_business_units b ON b.id=p.business_unit_id;
