CREATE TRIGGER management_sync_finance_months AFTER UPDATE OF revenue,cost_of_sales,sga_people,sga_cloud,sga_marketing,sga_rent,sga_travel,sga_other ON finance_months BEGIN
UPDATE management_values SET is_closed=CASE WHEN value IS NOT NEW.revenue THEN 0 ELSE is_closed END,value=NEW.revenue,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE entity_type='finance_month' AND entity_id=NEW.id AND metric='revenue' AND scenario='actual';
