INSERT INTO management_values(organization_id,entity_type,entity_id,metric,scenario,period,value,updated_at) SELECT d.organization_id,'kpi',t.id,'actual','actual','current',t.actual,t.updated_at FROM kpis t JOIN goals g ON g.id=t.goal_id JOIN departments d ON d.id=g.department_id;
CREATE TRIGGER management_sync_kpis AFTER UPDATE OF actual ON kpis BEGIN
UPDATE management_values SET is_closed=CASE WHEN value IS NOT NEW.actual THEN 0 ELSE is_closed END,value=NEW.actual,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE entity_type='kpi' AND entity_id=NEW.id AND metric='actual' AND scenario='actual' AND period='current';
END;
INSERT INTO management_values(organization_id,entity_type,entity_id,metric,scenario,period,value)
 SELECT d.organization_id,'kpi',h.kpi_id,'actual','actual',h.month,h.value FROM kpi_history h JOIN kpis k ON k.id=h.kpi_id JOIN goals g ON g.id=k.goal_id JOIN departments d ON d.id=g.department_id;
CREATE TRIGGER management_sync_history AFTER UPDATE OF value ON kpi_history BEGIN
 UPDATE management_values SET is_closed=CASE WHEN value IS NOT NEW.value THEN 0 ELSE is_closed END,value=NEW.value,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE entity_type='kpi' AND entity_id=NEW.kpi_id AND metric='actual' AND scenario='actual' AND period=NEW.month;
END;
-- Changing a canonical amount invalidates closure; source is retained.
-- No budgets, forecasts, prior years or milestones are inferred. Missing rows represent null.

ALTER TABLE finance_invoices ADD COLUMN owner TEXT;
